/**
 * Generated by scaffold-test-specs from MODULE_PLAN.yaml entry for CartItem.
 *
 * Endpoints under test (CRUD module):
 *   GET    /api/cart-items           — list (paginated)
 *   GET    /api/cart-items/:id       — read by id
 *   POST   /api/cart-items           — create
 *   PATCH  /api/cart-items/:id       — update
 *   DELETE /api/cart-items/:id       — soft-delete
 *
 * Coverage per endpoint:
 *   - happy path with correct cookie + valid body → declared 2xx
 *   - auth boundary: no cookie → 401
 *   - role boundary: wrong role → 403 (only when role_required != null)
 *
 * LLM-generate-tests fanout may APPEND additional describes for
 * domain-specific edge cases. The 3 base describes above are scaffolded;
 * do not rewrite them.
 */
import supertest from 'supertest';
import {
  createTestApp,
  closeTestApp,
  type TestAppContext,
} from '../setup/test-app.factory';
import { cleanDatabase } from '../setup/test-database';
import { createTestUser } from '../fixtures/user.fixture';
import { loginAndGetCookie } from '../fixtures/auth.fixture';
import { RoleEnum } from '../../src/common/enums/role.enum';

describe('CartItem E2E (CRUD)', () => {
  let ctx: TestAppContext;
  let cookie: string;

  beforeAll(async () => {
    ctx = await createTestApp();
  });

  beforeEach(async () => {
    await cleanDatabase(ctx.dataSource);
    // The signed-in user has to exist AFTER the truncate, not before it. This block used to
    // sit in beforeAll while cleanDatabase ran in beforeEach, so from the very first test the
    // cookie authenticated a user row that had just been deleted: every authenticated write
    // then failed the users FK and the exception filter mapped the constraint to 400. The
    // suites read as "the payload is wrong" — they were fine; the session's user was gone.
    const admin = await createTestUser(ctx.dataSource, {
      email: 'cart-item-spec-admin@test.com',
      role: RoleEnum.admin,
    });
    cookie = await loginAndGetCookie(ctx.app, admin.email, admin.password);

  });

  afterAll(async () => {
    await closeTestApp(ctx);
  });

  describe('GET /api/cart-items', () => {
    it('returns list with cookie (200)', async () => {
      await supertest(ctx.app.getHttpServer())
        .get('/api/cart-items')
        .set('Cookie', cookie)
        .expect(200);
    });

    it('returns 401 without cookie', async () => {
      await supertest(ctx.app.getHttpServer())
        .get('/api/cart-items')
        .expect(401);
    });

  });

  describe('GET /api/cart-items/:id', () => {
    it('returns 404 (or 400) for non-existent id with cookie', async () => {
      await supertest(ctx.app.getHttpServer())
        .get('/api/cart-items/00000000-0000-0000-0000-000000000000')
        .set('Cookie', cookie)
        .expect((res) => {
          if (![400, 404].includes(res.status)) {
            throw new Error(`Expected 404 (or 400 from ParseUUIDPipe) but got ${res.status}: ${JSON.stringify(res.body).slice(0, 200)}`);
          }
        });
    });

    it('returns 401 without cookie', async () => {
      await supertest(ctx.app.getHttpServer())
        .get('/api/cart-items/00000000-0000-0000-0000-000000000000')
        .expect(401);
    });
  });

  describe('POST /api/cart-items', () => {
    it('rejects empty body with 400 (or 422) validation error', async () => {
      await supertest(ctx.app.getHttpServer())
        .post('/api/cart-items')
        .set('Cookie', cookie)
        .send({})
        .expect((res) => {
          if (![400, 422].includes(res.status)) {
            throw new Error(`Expected 400/422 for empty body but got ${res.status}`);
          }
        });
    });

    it('returns 401 without cookie', async () => {
      await supertest(ctx.app.getHttpServer())
        .post('/api/cart-items')
        .send({})
        .expect(401);
    });

  });

  describe('PATCH /api/cart-items/:id', () => {
    it('returns 401 without cookie', async () => {
      await supertest(ctx.app.getHttpServer())
        .patch('/api/cart-items/00000000-0000-0000-0000-000000000000')
        .send({})
        .expect(401);
    });
  });

  describe('DELETE /api/cart-items/:id', () => {
    it('returns 401 without cookie', async () => {
      await supertest(ctx.app.getHttpServer())
        .delete('/api/cart-items/00000000-0000-0000-0000-000000000000')
        .expect(401);
    });

  });
});
